dashboard.definition:
{
  "title": "3 · AI Agent Governance (Studio)",
  "description": "A Claude agent goes off-script. Teleport stops it. Splunk shows exactly what happened.",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-15d@d,now"
      }
    },
    "input_src": {
      "type": "input.dropdown",
      "title": "Data source",
      "options": {
        "token": "src",
        "defaultValue": "index=teleport_demo",
        "items": [
          {
            "label": "Demo data (synthetic, 15 days)",
            "value": "index=teleport_demo"
          },
          {
            "label": "Live lab data",
            "value": "index=teleport"
          },
          {
            "label": "Both",
            "value": "(index=teleport OR index=teleport_demo)"
          }
        ]
      }
    },
    "input_agent": {
      "type": "input.text",
      "title": "Machine identity (name or bot-*)",
      "options": {
        "token": "agent",
        "defaultValue": "bot-*"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    },
    "tokens": {
      "default": {
        "agent": {
          "value": "bot-*"
        },
        "sel_day": {
          "value": "__none__"
        },
        "sel_actor": {
          "value": "*"
        },
        "sel_uid": {
          "value": "__none__"
        }
      }
    }
  },
  "dataSources": {
    "ds_base": {
      "type": "ds.search",
      "options": {
        "query": "$src$ sourcetype=teleport:audit\n| eval actor=coalesce(user, 'identity.user', user_name, \"unknown\")\n| eval actor_type=case(like(actor,\"bot-%\"),\"machine\", actor=\"system\",\"system\", like(actor,\"%.localhost\"),\"system\", true(),\"human\")\n| eval actor_class=case(actor_type=\"human\",\"human\", match(actor,\"^bot-(claude|copilot|lab)\"),\"ai_agent\", actor_type=\"machine\",\"workload\", true(),\"system\")\n| eval outcome=if(success=\"false\" OR like(code,\"%W\"),\"denied\",\"allowed\")\n| eval src=coalesce('addr.remote','identity.client_ip')\n| eval src_ip=replace(src,\":\\d+$$\",\"\")\n| eval resource=coalesce(db_service, app_name, server_hostname, kubernetes_cluster)\n| eval hour_utc=floor((_time%86400)/3600)\n| eval ttl_h=if(event=\"cert.create\", round((strptime(substr('identity.expires',1,19).\"+0000\",\"%Y-%m-%dT%H:%M:%S%z\")-_time)/3600,2), null())\n| eval is_write=if(event=\"db.session.query\" AND match(db_query,\"(?i)^\\s*(create|drop|alter|insert|update|delete|truncate|grant)\"),1,0)\n| fields _time, event, code, user, success, error, method, mfa_device, name, roles, login, sid, uid, db_service, db_name, db_user, db_query, app_name, server_hostname, kubernetes_cluster, verb, request_path, response_code, bot_name, user_name, \"identity.user\", \"identity.roles{}\", \"identity.expires\", \"identity.client_ip\", \"addr.remote\", demo, actor, actor_type, actor_class, outcome, src, src_ip, resource, hour_utc, ttl_h, is_write",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "base"
    },
    "ds_ag": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base",
        "query": "| search actor=\"$agent$\""
      }
    },
    "k1": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_ag",
        "query": "| eventstats count(eval(event=\"db.session.start\" AND outcome=\"allowed\")) as total | timechart span=1d count(eval(event=\"db.session.start\" AND outcome=\"allowed\")) as events, first(total) as total | eventstats max(total) as total"
      }
    },
    "k2": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_ag",
        "query": "| eventstats count(eval(event=\"db.session.query\" AND is_write=0)) as total | timechart span=1d count(eval(event=\"db.session.query\" AND is_write=0)) as events, first(total) as total | eventstats max(total) as total"
      }
    },
    "k3": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_ag",
        "query": "| eventstats count(eval(is_write=1)) as total | timechart span=1d count(eval(is_write=1)) as events, first(total) as total | eventstats max(total) as total"
      }
    },
    "k4": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_ag",
        "query": "| eventstats count(eval((event=\"db.session.start\" OR event=\"auth\") AND outcome=\"denied\")) as total | timechart span=1d count(eval((event=\"db.session.start\" OR event=\"auth\") AND outcome=\"denied\")) as events, first(total) as total | eventstats max(total) as total"
      }
    },
    "k5": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_ag",
        "query": "| search event=\"cert.create\" | stats avg(ttl_h) as h | eval h=round(h,1) | fields h"
      }
    },
    "c1": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_ag",
        "query": "| search event IN (\"db.session.query\",\"db.session.start\",\"auth\") | eval kind=case(is_write=1,\"tried to change data\",outcome=\"denied\" AND event IN (\"db.session.start\",\"auth\"),\"refused by Teleport\",event=\"db.session.query\",\"normal read\") | where isnotnull(kind) | timechart span=1d count by kind"
      }
    },
    "t1": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_ag",
        "query": "| stats dc(resource) as resources, values(resource) as reaches, values(db_user) as as_db_user, avg(ttl_h) as avg_cert_hours by actor | eval reaches=mvjoin(mvindex(reaches,0,2),\", \"), as_db_user=mvjoin(mvindex(as_db_user,0,2),\", \"), avg_cert_hours=round(avg_cert_hours,1)"
      }
    },
    "t2": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_ag",
        "query": "| eval day=strftime(_time,\"%Y-%m-%d\") | stats count(eval(event=\"db.session.query\" AND is_write=0)) as normal_reads, sum(is_write) as tried_to_change_data, count(eval(event=\"db.session.start\" AND outcome=\"denied\")) as admin_login_refused, count(eval(event=\"auth\" AND outcome=\"denied\")) as ssh_refused by day, actor | eval refused_total=tried_to_change_data+admin_login_refused+ssh_refused | eval verdict=case(refused_total>=6,\"Went off-script, stopped every time\",refused_total>0,\"Probed, stopped\",true(),\"Normal day\") | sort 0 - refused_total - day | table day actor verdict normal_reads tried_to_change_data admin_login_refused ssh_refused"
      }
    },
    "t3": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_ag",
        "query": "| eval day=strftime(_time,\"%Y-%m-%d\") | search day=\"$sel_day$\" actor=\"$sel_actor$\" | where event IN (\"bot.join\",\"cert.create\",\"db.session.start\",\"db.session.query\",\"db.session.query.failed\",\"auth\") | sort 0 _time | streamstats count as step | eval time=strftime(_time,\"%H:%M:%S\") | eval what_it_did=case(event=\"bot.join\",\"Agent starts and joins with its own bot identity\",event=\"cert.create\",\"Teleport issues a short-lived certificate (\".\"\".ttl_h.\" hour)\",event=\"db.session.start\" AND outcome=\"allowed\",\"Opens a database session as \".db_user,event=\"db.session.start\",\"Asks to connect as the admin database user: \".db_user,event=\"db.session.query\" AND is_write=1,\"TRIES TO CHANGE DATA: \".db_query,event=\"db.session.query\",\"Reads: \".db_query,event=\"db.session.query.failed\",\"The database runs it and rejects it\",event=\"auth\",\"Tries to open SSH as \".login,true(),event) | eval result=case(outcome=\"denied\",\"REFUSED\",is_write=1,\"Sent on, and logged\",true(),\"Allowed\") | eval stopped_by=case(event=\"db.session.start\" AND outcome=\"denied\",\"Teleport: this role has no admin database user\",event=\"auth\" AND outcome=\"denied\",\"Teleport: this role has no SSH access\",event=\"db.session.query.failed\",\"The read-only database user\",is_write=1,\"Next step: the read-only database user\",true(),\"\") | table step time what_it_did result stopped_by uid"
      }
    },
    "t4": {
      "type": "ds.search",
      "options": {
        "query": "$src$ sourcetype=teleport:audit uid=\"$sel_uid$\" | eval actor=coalesce(user,'identity.user',user_name) | eval evidence=_raw | table _time actor event code evidence",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "evidence"
    }
  },
  "visualizations": {
    "v_k1": {
      "type": "splunk.singlevalue",
      "title": "DATABASE SESSIONS",
      "dataSources": {
        "primary": "k1"
      },
      "options": {
        "majorColor": "#4E9BE0",
        "sparklineDisplay": "below",
        "trendDisplay": "off",
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValues": "> primary | seriesByName('events')",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#4E9BE0",
        "sparklineAreaColor": "#4E9BE0",
        "backgroundColor": "#141B27",
        "majorFontSize": 56
      }
    },
    "v_k2": {
      "type": "splunk.singlevalue",
      "title": "NORMAL READS",
      "dataSources": {
        "primary": "k2"
      },
      "options": {
        "majorColor": "#3FB68B",
        "sparklineDisplay": "below",
        "trendDisplay": "off",
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValues": "> primary | seriesByName('events')",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#3FB68B",
        "sparklineAreaColor": "#3FB68B",
        "backgroundColor": "#141B27",
        "majorFontSize": 56
      }
    },
    "v_k3": {
      "type": "splunk.singlevalue",
      "title": "TRIED TO CHANGE DATA",
      "dataSources": {
        "primary": "k3"
      },
      "options": {
        "majorColor": "> majorValue | rangeValue(majorColorCfg)",
        "sparklineDisplay": "below",
        "trendDisplay": "off",
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValues": "> primary | seriesByName('events')",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#3FB68B",
        "sparklineAreaColor": "#3FB68B",
        "backgroundColor": "#141B27",
        "majorFontSize": 56
      },
      "context": {
        "majorColorCfg": [
          {
            "to": 1,
            "value": "#3FB68B"
          },
          {
            "from": 1,
            "value": "#F0A030"
          }
        ]
      }
    },
    "v_k4": {
      "type": "splunk.singlevalue",
      "title": "REFUSED BY TELEPORT",
      "dataSources": {
        "primary": "k4"
      },
      "options": {
        "majorColor": "> majorValue | rangeValue(majorColorCfg)",
        "sparklineDisplay": "below",
        "trendDisplay": "off",
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValues": "> primary | seriesByName('events')",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#3FB68B",
        "sparklineAreaColor": "#3FB68B",
        "backgroundColor": "#141B27",
        "majorFontSize": 56
      },
      "context": {
        "majorColorCfg": [
          {
            "to": 1,
            "value": "#3FB68B"
          },
          {
            "from": 1,
            "value": "#E5534B"
          }
        ]
      }
    },
    "v_k5": {
      "type": "splunk.singlevalue",
      "title": "CREDENTIAL LIFETIME (HOURS)",
      "dataSources": {
        "primary": "k5"
      },
      "options": {
        "majorColor": "#F0A030",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "backgroundColor": "#141B27",
        "majorFontSize": 56
      }
    },
    "v_c1": {
      "type": "splunk.column",
      "title": "Most days it just reads. The spikes are the bad days.",
      "dataSources": {
        "primary": "c1"
      },
      "options": {
        "backgroundColor": "#141B27",
        "legendDisplay": "bottom",
        "stackMode": "stacked",
        "seriesColorsByField": {
          "normal read": "#3FB68B",
          "tried to change data": "#F0A030",
          "refused by Teleport": "#E5534B"
        }
      }
    },
    "v_t1": {
      "type": "splunk.table",
      "title": "The job it was given: what can this identity reach?",
      "dataSources": {
        "primary": "t1"
      },
      "options": {
        "count": 6,
        "backgroundColor": "#141B27",
        "dataOverlayMode": "none",
        "showRowNumbers": false,
        "wrap": true
      }
    },
    "v_t2": {
      "type": "splunk.table",
      "title": "Which day went wrong? Click the worst one.",
      "dataSources": {
        "primary": "t2"
      },
      "options": {
        "count": 6,
        "backgroundColor": "#141B27",
        "dataOverlayMode": "none",
        "showRowNumbers": false,
        "wrap": true,
        "columnFormat": {
          "verdict": {
            "rowBackgroundColors": "> table | seriesByName(\"verdict\") | matchValue(verdictBg)"
          }
        }
      },
      "context": {
        "verdictBg": [
          {
            "match": "Went off-script, stopped every time",
            "value": "#7A2B27"
          },
          {
            "match": "Probed, stopped",
            "value": "#7A5A1A"
          },
          {
            "match": "Normal day",
            "value": "#1F4E3A"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "sel_day",
                "key": "row.day.value"
              },
              {
                "token": "sel_actor",
                "key": "row.actor.value"
              }
            ]
          }
        },
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "sel_uid",
                "value": "__none__"
              }
            ]
          }
        }
      ]
    },
    "v_t3": {
      "type": "splunk.table",
      "title": "The story of that day, step by step. Click a step for the raw evidence.",
      "dataSources": {
        "primary": "t3"
      },
      "options": {
        "count": 20,
        "backgroundColor": "#141B27",
        "dataOverlayMode": "none",
        "showRowNumbers": false,
        "wrap": true,
        "columnFormat": {
          "result": {
            "rowBackgroundColors": "> table | seriesByName(\"result\") | matchValue(resultBg)"
          }
        }
      },
      "context": {
        "resultBg": [
          {
            "match": "REFUSED",
            "value": "#7A2B27"
          },
          {
            "match": "Sent on, and logged",
            "value": "#7A5A1A"
          },
          {
            "match": "Allowed",
            "value": "#1F4E3A"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "sel_uid",
                "key": "row.uid.value"
              }
            ]
          }
        }
      ]
    },
    "v_t4": {
      "type": "splunk.table",
      "title": "The evidence: the audit event exactly as Teleport wrote it",
      "dataSources": {
        "primary": "t4"
      },
      "options": {
        "count": 3,
        "backgroundColor": "#141B27",
        "dataOverlayMode": "none",
        "showRowNumbers": false,
        "wrap": true
      }
    },
    "v_n": {
      "type": "splunk.markdown",
      "options": {
        "backgroundColor": "#141B27",
        "fontColor": "#E6EDF7",
        "markdown": "**The story in one breath:** a Claude agent was given a narrow job: read one database, with a certificate that lasts about an hour. Then it went off-script. It asked for the admin database user, tried to drop and change a table, and tried to open SSH. **Nothing landed.** Teleport refused the admin login and the SSH. The read-only database user rejected the writes. Every attempt is in one log with a unique event ID.  \n*Honest detail:* a write shown as sent on and logged means Teleport forwarded the query; the read-only database user is what refuses it. The database-rejection event shape is approximated in this synthetic data."
      }
    },
    "v_l1": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## ①  The setup: a narrow job and a credential that expires",
        "fontColor": "#4E9BE0",
        "backgroundColor": "transparent"
      }
    },
    "v_l2": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## ②  Which day went wrong?",
        "fontColor": "#F0A030",
        "backgroundColor": "transparent"
      }
    },
    "v_l3": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## ③  What happened that day, step by step",
        "fontColor": "#E5534B",
        "backgroundColor": "transparent"
      }
    },
    "v_l4": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## ④  The proof",
        "fontColor": "#3FB68B",
        "backgroundColor": "transparent"
      }
    },
    "v_bar": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#B07CE8",
        "strokeColor": "#B07CE8",
        "rx": 4
      }
    },
    "v_h1": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# Scene 3: an AI agent goes off-script",
        "fontColor": "#FFFFFF",
        "backgroundColor": "transparent"
      }
    },
    "v_h2": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "A separate machine identity, a read-only role, a one-hour credential. Watch what it tried, and what stopped it.",
        "fontColor": "#9FB3CC",
        "backgroundColor": "transparent"
      }
    }
  },
  "layout": {
    "type": "absolute",
    "options": {
      "width": 1920,
      "height": 2340,
      "display": "auto-scale",
      "backgroundColor": "#0B0F17"
    },
    "structure": [
      {
        "item": "v_bar",
        "type": "block",
        "position": {
          "x": 40,
          "y": 30,
          "w": 10,
          "h": 86
        }
      },
      {
        "item": "v_h1",
        "type": "block",
        "position": {
          "x": 68,
          "y": 24,
          "w": 1750,
          "h": 56
        }
      },
      {
        "item": "v_h2",
        "type": "block",
        "position": {
          "x": 68,
          "y": 82,
          "w": 1750,
          "h": 34
        }
      },
      {
        "item": "v_k1",
        "type": "block",
        "position": {
          "x": 40,
          "y": 140,
          "w": 350,
          "h": 190
        }
      },
      {
        "item": "v_k2",
        "type": "block",
        "position": {
          "x": 412,
          "y": 140,
          "w": 350,
          "h": 190
        }
      },
      {
        "item": "v_k3",
        "type": "block",
        "position": {
          "x": 784,
          "y": 140,
          "w": 350,
          "h": 190
        }
      },
      {
        "item": "v_k4",
        "type": "block",
        "position": {
          "x": 1156,
          "y": 140,
          "w": 350,
          "h": 190
        }
      },
      {
        "item": "v_k5",
        "type": "block",
        "position": {
          "x": 1528,
          "y": 140,
          "w": 350,
          "h": 190
        }
      },
      {
        "item": "v_l1",
        "type": "block",
        "position": {
          "x": 40,
          "y": 350,
          "w": 1840,
          "h": 36
        }
      },
      {
        "item": "v_l2",
        "type": "block",
        "position": {
          "x": 40,
          "y": 800,
          "w": 1840,
          "h": 36
        }
      },
      {
        "item": "v_l3",
        "type": "block",
        "position": {
          "x": 40,
          "y": 1170,
          "w": 1840,
          "h": 36
        }
      },
      {
        "item": "v_l4",
        "type": "block",
        "position": {
          "x": 40,
          "y": 1900,
          "w": 1840,
          "h": 36
        }
      },
      {
        "item": "v_c1",
        "type": "block",
        "position": {
          "x": 40,
          "y": 392,
          "w": 1000,
          "h": 380
        }
      },
      {
        "item": "v_t1",
        "type": "block",
        "position": {
          "x": 1062,
          "y": 392,
          "w": 818,
          "h": 380
        }
      },
      {
        "item": "v_t2",
        "type": "block",
        "position": {
          "x": 40,
          "y": 842,
          "w": 1840,
          "h": 300
        }
      },
      {
        "item": "v_t3",
        "type": "block",
        "position": {
          "x": 40,
          "y": 1212,
          "w": 1840,
          "h": 650
        }
      },
      {
        "item": "v_t4",
        "type": "block",
        "position": {
          "x": 40,
          "y": 1942,
          "w": 1840,
          "h": 190
        }
      },
      {
        "item": "v_n",
        "type": "block",
        "position": {
          "x": 40,
          "y": 2160,
          "w": 1840,
          "h": 150
        }
      }
    ],
    "globalInputs": [
      "input_time",
      "input_src",
      "input_agent"
    ]
  }
}
